import AppKit

public enum MinnieArtworkAssets {
    private static var cachedBody: NSImage?
    private static var cachedHourArm: NSImage?
    private static var cachedMinuteArm: NSImage?

    public static var bodyImage: NSImage? {
        if let cachedBody { return cachedBody }
        if let data = Data(base64Encoded: bodyBase64), let img = NSImage(data: data) {
            cachedBody = img
            return img
        }
        return nil
    }

    public static var hourArmImage: NSImage? {
        if let cachedHourArm { return cachedHourArm }
        if let data = Data(base64Encoded: hourArmBase64), let img = NSImage(data: data) {
            cachedHourArm = img
            return img
        }
        return nil
    }

    public static var minuteArmImage: NSImage? {
        if let cachedMinuteArm { return cachedMinuteArm }
        if let data = Data(base64Encoded: minuteArmBase64), let img = NSImage(data: data) {
            cachedMinuteArm = img
            return img
        }
        return nil
    }

    private static let bodyBase64 = ""
    private static let hourArmBase64 = ""
    private static let minuteArmBase64 = ""
}
